import { PCFSoftShadowMap } from "three";
import type { PageThreeConfig } from "../../../types/core.types.js";
import { getDefaultThreeConfig } from "../../../config/base.config.js";
import { EnvSetup } from "../../../app/EnvSetup.js";
import {
  mainBackground,
  cloud,
  cloud2,
  cloud3,
  cloud4,
  cloud5,
  cloud6,
  earth,
  ground,
  planet,
  rocket,
  jetEngine,
  gravityBalls,
  smokeFloor,
  sceneLights,
  terrian,
  sceneTransitionVeil,
  windowObj,
} from "../../../core/setup.js";
import {
  createMainInitialSceneState,
  createMainPostProcessingOptions,
} from "../theatre/MainSceneState.js";
import { MainSceneRig } from "../theatre/MainSceneRig.js";
import type {
  MainPageConfig,
  MainSceneSectionKey,
  MainTheatreSheetId,
} from "../../../types/main.types.js";
import { BlockReveal } from "../../../animation/BlockReveal.js";
import { TextReveal } from "../../../animation/TextReveal.js";
import { Helpers } from "../../../utils/Helpers.js";
import { runIntroDomTimeline } from "../../../runtime/IntroLoadingRuntime.js";
import { INIT_DOM_CLASSES } from "../../../config/dom.config.js";
import {
  MAIN_BACKGROUND_CLIENT_LOOK,
  MAIN_BACKGROUND_CONTACT_LOOK,
  MAIN_BACKGROUND_HERO_LOOK,
  MAIN_BACKGROUND_INTRO_LOOK,
  MAIN_BACKGROUND_INTRO_ACTION_LOOK,
  MAIN_BACKGROUND_SERVICES_LOOK,
  MAIN_BACKGROUND_STORY_LOOK,
  MAIN_BACKGROUND_WHO_LOOK,
  MAIN_BACKGROUND_WHY_LOOK,
  MAIN_BACKGROUND_WORKS_DETAIL_LOOK,
  MAIN_BACKGROUND_WORKS_FINAL_LOOK,
  MAIN_BACKGROUND_WORKS_LOOK,
} from "../../../config/background.config.js";
import {
  BACKGROUND_APP_DOM as APP_MANAGER_DOM,
  CONTACT_HEAD_TRANSITION,
  WORKS_DETAIL_HEAD_TRANSITION,
} from "../../../config/transition.config.js";
import type {
  PageSceneRuntimePolicy,
  SceneBackgroundPolicy,
  SceneProgressOptionsMap,
  SceneSelectorMap,
} from "../../../types/runtime.types.js";
import type {
  BackgroundTransitionRule,
  BackgroundVariantKey,
  SceneProgressTransitionWindow,
} from "../../../types/object-runtime.types.js";

const MAIN_THEATRE_QUERY_KEY = "theatre";
const MAIN_THEATRE_QUERY_ENABLED = "1";
const WHO_TEXT_SELECTOR = ".no-main-who .mask-target";
const WHO_REVEAL_START = 0.12;
const WHO_REVEAL_END = 0.92;
const WHO_REVEAL_STAGGER_SECONDS = 0.12;
const CLIENT_ITEM_SELECTOR = ".no-main-clients__item";
const CLIENT_REVEAL_START = 0.08;
const CLIENT_REVEAL_END = 0.96;
const CLIENT_REVEAL_STAGGER_SECONDS = 0.045;
const CONTACT_SECTION_SELECTOR = ".no-main-contact";
const CONTACT_HEAD_SELECTOR = ".no-main-contact__head";
const CONTACT_ACTIONS_SELECTOR = ".no-main-contact__actions";
const CONTACT_ACTION_ITEM_SELECTOR =
  ".no-main-contact__actions > .no-corner-btn-wrap";
const WORKS_DETAIL_HEAD_SELECTOR = APP_MANAGER_DOM.portfolioHeadSelector;
const MAIN_IS_AUTHOR_MODE = EnvSetup.hasQueryFlag(
  MAIN_THEATRE_QUERY_KEY,
  MAIN_THEATRE_QUERY_ENABLED,
);
const MAIN_SCENE_RIG = new MainSceneRig();
const mainInitialSceneState = createMainInitialSceneState();
const initialState = MAIN_SCENE_RIG.compose(
  mainInitialSceneState,
) as NonNullable<MainPageConfig["initialState"]>;
const initialCameraPosition = {
  x: initialState.camera?.position?.x ?? 0,
  y: initialState.camera?.position?.y ?? 0,
  z: initialState.camera?.position?.z ?? 0,
};
const initialCameraTargetPosition = {
  x: initialState.cameraTarget?.position?.x ?? 0,
  y: initialState.cameraTarget?.position?.y ?? 0,
  z: initialState.cameraTarget?.position?.z ?? 0,
};
const defaultThree = getDefaultThreeConfig();
const initialCameraFov = initialState.camera?.fov ?? defaultThree.camera.fov;
const initialPostProcessing = createMainPostProcessingOptions(
  mainInitialSceneState.postProcessing,
);
const mainSceneDomState = {
  isWhoTextVisible: false,
  whoTextTimers: [] as number[],
  isWorksDetailHeadVisible: false,
  worksDetailHeadTimers: [] as number[],
  isClientItemsVisible: false,
  clientItemTimers: [] as number[],
  isContactHeadVisible: false,
  contactHeadTimers: [] as number[],
  isContactActionsVisible: false,
  contactActionTimers: [] as number[],
  storyStatsFired: false,
};

function clearTimers(timerIds: number[]): number[] {
  timerIds.forEach((timerId) => {
    window.clearTimeout(timerId);
  });
  return [];
}

const STORY_STAT_SELECTOR = "[data-count-to]";
const STORY_STATS_SELECTOR = "[data-story-stats]";
const STORY_STAT_DURATION = 1800;
const STORY_STAT_STAGGER = 150;

function triggerStoryStats(): void {
  const items = Array.from(
    document.querySelectorAll<HTMLElement>(STORY_STAT_SELECTOR),
  );
  if (!items.length) return;

  items.forEach((el, i) => {
    const target = Number(el.dataset.countTo ?? 0);
    let startTime: number | null = null;

    function tick(ts: number): void {
      if (startTime === null) startTime = ts;
      const t = Math.min((ts - startTime) / STORY_STAT_DURATION, 1);
      const eased = 1 - Math.pow(1 - t, 3);
      el.textContent = Math.round(eased * target).toString();
      if (t < 1) requestAnimationFrame(tick);
    }

    window.setTimeout(() => requestAnimationFrame(tick), i * STORY_STAT_STAGGER);
  });
}

function initStoryStatsObserver(): void {
  const container = document.querySelector<HTMLElement>(STORY_STATS_SELECTOR);
  if (!container) return;
  const observer = new IntersectionObserver(
    (entries) => {
      const entry = entries[0];
      if (!entry?.isIntersecting) return;
      if (mainSceneDomState.storyStatsFired) return;
      mainSceneDomState.storyStatsFired = true;
      observer.disconnect();
      triggerStoryStats();
    },
    { threshold: 0.35 },
  );
