330	  override runUpdate(deltaTime: number): void {
331	    if (!this._built) return;
332	    const root = this.getTimelineRoot();
333	    if (!root?.visible) return;
334	    const camera = this._context?.camera as THREE.PerspectiveCamera | undefined;
335	    if (!camera) return;
336	
337	    this._projScreenMatrix.multiplyMatrices(
338	      camera.projectionMatrix,
339	      camera.matrixWorldInverse,
