341	    this._frustum.setFromProjectionMatrix(this._projScreenMatrix);
342	    root.getWorldPosition(this._frustumSphere.center);
343	    this._frustumSphere.radius = JetEngine.FRUSTUM_CULL_RADIUS;
344	    if (!this._frustum.intersectsSphere(this._frustumSphere)) return;
345	
346	    const { flameLen, throttle, elapsed } = this._sim.update(deltaTime);
347	    const flameLenScaled = flameLen * this._intensity;
348	    const throttleScaled = throttle * this._intensity;
349	
350	    // Single write propagates to all shared-reference materials
351	    this._uTime.value = elapsed;
352	    this._uFlameLen.value = flameLenScaled;
353	    this._uThrottle.value = throttleScaled;
354	
355	    for (const eng of this._inner) {
356	      eng.group.scale.y = this._cfg.baseLength * flameLenScaled;
357	    }
358	
359	    const parent = this._parent;
360	    if (!parent) return;
361	    parent.group.scale.y = this._cfg.parentLength * flameLenScaled;
362	
363	    // Only propagate quaternion when camera actually rotates
364	    const camQ = camera.quaternion;
365	    if (!camQ.equals(this._lastCamQ)) {
366	      this._lastCamQ.copy(camQ);
367	      for (const eng of this._inner) {
368	        for (const b of eng.blooms) b.mesh.quaternion.copy(camQ);
369	      }
370	      for (const b of parent.blooms) b.mesh.quaternion.copy(camQ);
371	    }
372	
373	    // Skip bloom intensity writes when flame is effectively invisible
374	    if (flameLenScaled > 0.02) {
