571	  private _syncDynamicUniforms(cfg: JetEngineResolvedConfig): void {
572	    const inn = this._uInner;
573	    inn.noiseSpeedR.value = 2.8 * cfg.innerNoiseSpeed;
574	    inn.noiseSpeedL.value = 2.2 * cfg.innerNoiseSpeed;
