578	    inn.fragSpeed2.value  = 4.5  * cfg.innerNoiseSpeed;
579	    inn.colorTop.value.setRGB(...cfg.innerColor.top);
580	    inn.colorTip.value.setRGB(...cfg.innerColor.tip);
581	    const flash = cfg.innerColor.top.map((v) => Math.min(1, v + 0.2)) as RGB;
582	    inn.colorFlash.value.setRGB(...flash);
583	
584	    const par = this._uParent;
585	    par.noiseSpeedR.value = 2.4 * cfg.parentNoiseSpeed;
586	    par.noiseSpeedL.value = 1.8 * cfg.parentNoiseSpeed;
587	    par.turbR.value       = 0.18 * cfg.turbulence;
588	    par.turbL.value       = 0.3  * cfg.turbulence;
589	    par.fragSpeed1.value  = 1.2  * cfg.parentNoiseSpeed;
590	    par.fragSpeed2.value  = 0.7  * cfg.parentNoiseSpeed;
591	    par.colorTop.value.setRGB(...cfg.parentColor.top);
592	    par.colorTip.value.setRGB(...cfg.parentColor.tip);
593	  }
594	
595	  private _syncNozzleAngles(cfg: JetEngineResolvedConfig): void {
596	    const nr = cfg.nozzleRadius;
597	    const gridStepX = nr * Math.max(0.2, cfg.nozzleGapX);
598	    const gridStepZ = nr * Math.max(0.2, cfg.nozzleGapZ);
599	    const tipY = -(cfg.baseLength * 0.85);
600	    const down = new THREE.Vector3(0, -1, 0);
601	    JetEngine.LAYOUT.forEach(([gx, gz], i) => {
602	      const eng = this._inner[i];
603	      if (!eng || (gx === 0 && gz === 0)) return;
604	      const pos = new THREE.Vector3(gx * gridStepX, 0, gz * gridStepZ);
605	      const dir = new THREE.Vector3(0, tipY, 0).sub(pos).normalize();
606	      eng.group.quaternion.setFromUnitVectors(down, dir);
607	    });
608	  }
609	
610	  private _teardown(): void {
611	    this._innerGeo?.dispose();
612	    this._innerGeo = null;
613	    for (const eng of this._inner) {
614	      eng.group.traverse((obj) => {
615	        if (obj instanceof THREE.Mesh) {
616	          (obj.material as THREE.Material).dispose();
617	        }
618	      });
619	      for (const b of eng.blooms) {
620	        b.mesh.geometry.dispose();
621	        b.mat.dispose();
622	      }
623	      eng.group.parent?.remove(eng.group);
624	    }
625	    if (this._parent) {
626	      this._parent.group.traverse((obj) => {
627	        if (obj instanceof THREE.Mesh) {
628	          obj.geometry.dispose();
629	          (obj.material as THREE.Material).dispose();
630	        }
631	      });
632	      for (const b of this._parent.blooms) {
633	        b.mesh.geometry.dispose();
634	        b.mat.dispose();
635	      }
636	      this._parent.group.parent?.remove(this._parent.group);
637	    }
638	  }
639	
640	  private _buildBlooms(
641	    parent: THREE.Group,
642	    layers: Array<{
643	      color: RGB;
644	      radius: number;
645	      size: number;
646	      baseI: number;
647	      y: number;
648	    }>,
649	  ): JetEngineBloomLayer[] {
650	    return layers.map((l, index) => {
651	      const geo = new THREE.PlaneGeometry(l.size, l.size);
652	      const mat = new THREE.ShaderMaterial({
653	        uniforms: {
654	          uTime: this._uTime,
655	          uColor: { value: new THREE.Color(...l.color) },
656	          uIntensity: { value: l.baseI },
657	          uRadius: { value: l.radius },
658	        },
659	        vertexShader: bloomVertRaw as string,
660	        fragmentShader: bloomFragRaw as string,
661	        transparent: true,
662	        depthWrite: false,
663	        blending: THREE.AdditiveBlending,
664	        side: THREE.DoubleSide,
665	      });
666	      this.registerShader({
667	        key: this.createShaderKey(`bloom.${parent.uuid}.${index}`),
668	        ownerId: this.getShaderOwnerId(),
669	        material: mat,
670	        autoResolution: false,
671	      });
672	      const mesh = new THREE.Mesh(geo, mat);
673	      mesh.position.y = l.y;
674	      mesh.layers.set(THREE_LAYER_ROCKET);
675	      mesh.renderOrder = JetEngine.MESH_RENDER_ORDER;
676	      parent.add(mesh);
677	      return { mesh, mat, baseIntensity: l.baseI, yOffset: l.y };
678	    });
679	  }
680	
681	}
