14	const float FLAME_CENTER_Y = 0.2;
15	const float FLAME_FADE_MULT = 1.35;
16	const float FLAME_FADE_POW = 2.5;
17	const float FLAME_HUE = 0.0;
18	const float FLAME_SATURATION = 1.1;
19	const float FLAME_TEMPERATURE = 1.1;
20	const float FLAME_BASE_WIDTH = 1.8;
21	const float FLAME_TAPER = 2.5;
22	const float FLAME_VERT_STRETCH = 0.75;
23	const float FLAME_NOISE_DISTORTION = 1.4;
24	const float FLAME_EDGE_SOFTNESS = 1.2;
25	const float FLICKER_STRENGTH = 0.25;
26	const float FLICKER_SPEED = 2.0;
27	const float ASYMMETRY_STRENGTH = 0.01;
28	const float ASYMMETRY_SPEED = 0.03;
29	const float TEMP_MOD_STRENGTH = 0.1;
30	const float TEMP_MOD_SPEED = 0.3;
31	const float TURBULENCE_MIX = 0.4;
32	const float SMOKE_HEIGHT = 1.2;
33	const float SMOKE_STRENGTH = 0.3;
34	
35	vec3 hsv2rgb(vec3 c) {
36	  vec3 rgb = clamp(
37	    abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0,
38	    0.0,
39	    1.0
40	  );
41	  rgb = rgb * rgb * (3.0 - 2.0 * rgb);
42	  return c.z * mix(vec3(1.0), rgb, c.y);
43	}
44	
45	vec2 hash(vec2 p) {
46	  p = vec2(
47	    dot(p, vec2(127.1, 311.7)),
48	    dot(p, vec2(269.5, 183.3))
49	  );
50	  return -1.0 + 2.0 * fract(sin(p) * 43758.5453123);
51	}
52	
53	float noise(in vec2 p) {
54	  const float K1 = 0.366025404;
55	  const float K2 = 0.211324865;
56	
57	  vec2 cell = floor(p + (p.x + p.y) * K1);
58	  vec2 a = p - cell + (cell.x + cell.y) * K2;
59	  vec2 offset = (a.x > a.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
60	  vec2 b = a - offset + K2;
61	  vec2 c = a - 1.0 + 2.0 * K2;
62	
63	  vec3 h = max(0.5 - vec3(dot(a, a), dot(b, b), dot(c, c)), 0.0);
64	  vec3 grad = vec3(
65	    dot(a, hash(cell + 0.0)),
66	    dot(b, hash(cell + offset)),
67	    dot(c, hash(cell + 1.0))
68	  );
69	
70	  vec3 n = h * h * h * h * grad;
71	  return dot(n, vec3(70.0));
72	}
73	
74	float fbm(vec2 uv) {
75	  float value;
76	  mat2 rotScale = mat2(1.6, 1.2, -1.2, 1.6);
77	
78	  value = 0.5000 * noise(uv);
79	  uv = rotScale * uv;
80	  value += 0.2500 * noise(uv);
81	  uv = rotScale * uv;
82	  value += 0.1250 * noise(uv);
83	
84	  return 0.5 + 0.5 * value;
85	}
86	
87	vec2 toFlameUV(vec2 uv) {
88	  vec2 center = vec2(FLAME_CENTER_X, FLAME_CENTER_Y);
89	  vec2 scale = vec2(FLAME_SCALE_X, FLAME_SCALE_Y);
90	  return (uv - center) / scale;
91	}
92	
